use crate::{SDL_EventType, SDL_KeyboardID, SDL_Keycode, SDL_Keymod, SDL_Scancode, SDL_WindowID};

/// Keyboard button event structure (event.key.*)
///
/// # Remarks
/// The key is the base [`SDL_Keycode`] generated by pressing the scancode using the current
/// keyboard layout, applying any options specified in [`SDL_HINT_KEYCODE_OPTIONS`]. You can get
/// the [`SDL_Keycode`] corresponding to the event scancode and modifiers directly from the
/// keyboard layout, bypassing [`SDL_HINT_KEYCODE_OPTIONS`], by calling [`SDL_GetKeyFromScancode`].
#[repr(C)]
#[derive(Debug, Clone, Copy)]
#[allow(non_camel_case_types)]
pub struct SDL_KeyboardEvent {
    /// [`SDL_EventType::KeyDown`] or [`SDL_EventType::KeyUp`]
    pub r#type: SDL_EventType,

    #[allow(missing_docs)]
    pub reserved: u32,

    /// In nanoseconds, populated using [`SDL_GetTicksNS`]
    pub timestamp: u64,

    /// The window with keyboard focus, if any
    pub window_id: SDL_WindowID,

    /// The keyboard instance id, or 0 if unknown or virtual
    pub which: SDL_KeyboardID,

    /// SDL physical key code
    pub scancode: SDL_Scancode,

    /// SDL virtual key code
    pub key: SDL_Keycode,

    /// current key modifiers
    pub r#mod: SDL_Keymod,

    /// The platform dependent scancode for this event
    pub raw: u16,

    /// `true` if the key is pressed
    pub down: bool,

    /// `true` if this is a key repeat
    pub repeat: bool,
}

impl Default for SDL_KeyboardEvent {
    fn default() -> Self {
        SDL_KeyboardEvent {
            r#type: SDL_EventType::First,
            reserved: 0,
            timestamp: 0,
            window_id: 0,
            which: 0,
            scancode: SDL_Scancode::Unknown,
            key: 0,
            r#mod: 0,
            raw: 0,
            down: false,
            repeat: false,
        }
    }
}
